      "hasObjectPhoto": true,
      "labelEvidence": "家族青铜器的重要原因\n防墓葬中\n宝鸡地区西部作为传\n统的非姬姓周人聚居地，其石\n些青铜器往往作为联姻\n鼓山、戴家湾以及弹国墓地中\n征，见证了当时家族间\n出士的商代青钢器，部分便是\n系与合作。\n灭商之后作为分器或战利品被\n赐予当地功臣的。",
