      "hasObjectPhoto": true,
      "treasureId": "lai-pan",
      "labelEvidence": "速ai盘\n时代：西周晚期\n来源：2003年眉县马家镇杨家村窖藏出土\n收藏单位：中国青铜器博物院\nWaterbasin of Lai\nLateWestermZhou\n速（i盘\n时代：西周晚期\n来源：2003年眉县马家镇杨家村窖藏出土\n收藏单位：中国青铜器博物院\nWaterbasin of Lai\nLate Westerm Zhou\nExcavatedfrom thehoard inYangjiacunVillage,MajiaTown,MeixianCountyin2003\nCollection ofBaojiBronzeWareMuseum\n此为复制品",
